bounded_host_request.command:
set -eu
docker exec -i deploy-postgres-1 sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"' <<'SQL'
BEGIN;
DO $$
DECLARE n int;
BEGIN
SELECT count(*) INTO n FROM posting_topics
 WHERE board_key='video_chat' AND chat_id=-1002373696859 AND message_thread_id=1695
 AND purpose='announcement' AND title ILIKE '%稼げる有料動画投稿%'
 AND enabled=TRUE AND verified_by IS NOT NULL AND verified_at IS NOT NULL;
IF n <> 1 THEN RAISE EXCEPTION 'VERIFIED_ORIGINAL_VIDEO_TOPIC_MISSING'; END IF;
SELECT count(*) INTO n FROM posting_topics WHERE purpose='video_sale' AND enabled=TRUE;
IF n > 1 THEN RAISE EXCEPTION 'AMBIGUOUS_VIDEO_SALE_ROUTES'; END IF;
IF n=1 AND NOT EXISTS(SELECT 1 FROM posting_topics WHERE purpose='video_sale' AND enabled=TRUE AND board_key='video_chat' AND chat_id=-1002373696859 AND message_thread_id=1695) THEN RAISE EXCEPTION 'VIDEO_SALE_ROUTE_CONFLICT'; END IF;
END $$;
INSERT INTO posting_topics (board_key,purpose,chat_id,message_thread_id,title,verified_by,verified_at,enabled)
 SELECT board_key,'video_sale',chat_id,message_thread_id,title,verified_by,verified_at,TRUE
 FROM posting_topics WHERE board_key='video_chat' AND chat_id=-1002373696859
 AND message_thread_id=1695 AND purpose='announcement'
 AND title ILIKE '%稼げる有料動画投稿%' AND enabled=TRUE
 AND verified_by IS NOT NULL AND verified_at IS NOT NULL
 ON CONFLICT(board_key,purpose,chat_id,message_thread_id) DO NOTHING;
DO $$
BEGIN
IF (SELECT count(*) FROM posting_topics WHERE purpose='video_sale' AND enabled=TRUE AND chat_id=-1002373696859 AND message_thread_id=1695 AND verified_by IS NOT NULL) <> 1
THEN RAISE EXCEPTION 'VIDEO_SALE_BIND_READBACK_FAILED'; END IF;
END $$;
COMMIT;
SELECT 'VIDEO_SALE_ROUTE_VERIFIED='||count(*) FROM posting_topics
 WHERE purpose='video_sale' AND enabled=TRUE AND chat_id=-1002373696859 AND message_thread_id=1695 AND verified_by IS NOT NULL;
SQL
